import{_ as n,o as a,c as p,a3 as e}from"./chunks/framework.CNCDq11_.js";const o=JSON.parse('{"title":"AI 提示词","description":"","frontmatter":{},"headers":[],"relativePath":"ai/prompt/index.md","filePath":"ai/prompt/index.md"}'),l={name:"ai/prompt/index.md"};function i(t,s,r,c,b,d){return a(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="ai-提示词" tabindex="-1">AI 提示词 <a class="header-anchor" href="#ai-提示词" aria-label="Permalink to &quot;AI 提示词&quot;">​</a></h1><p>提示词（Prompt）是用户与大语言模型交互时输入的指令文本。写好提示词的核心不是背诵固定咒语，而是把「角色、任务、上下文、输出格式、约束」这几个要素组织清楚。本页记录提示词的基础概念、常用技巧和可复用的场景模板。</p><blockquote><p>提示词的效果因模型版本和任务类型而异，以下内容是通用思路而非万能公式，实际使用时需要结合具体模型迭代调整。</p></blockquote><h2 id="基础概念" tabindex="-1">基础概念 <a class="header-anchor" href="#基础概念" aria-label="Permalink to &quot;基础概念&quot;">​</a></h2><p>一个结构完整的提示词通常包含以下要素：</p><table tabindex="0"><thead><tr><th>要素</th><th>作用</th><th>示例</th></tr></thead><tbody><tr><td>角色</td><td>约束模型回答的视角和口吻</td><td>「你是一位资深前端工程师」</td></tr><tr><td>任务</td><td>明确要做什么</td><td>「请审查下面的代码」</td></tr><tr><td>上下文</td><td>提供背景信息，减少模型自由发挥</td><td>技术栈、项目背景、目标读者</td></tr><tr><td>输出格式</td><td>规定返回结构，便于解析</td><td>「以 Markdown 表格输出」</td></tr><tr><td>约束条件</td><td>划定边界，避免不想要的输出</td><td>「不要引入新依赖」</td></tr></tbody></table><p>不需要每次都写全五个要素，但<strong>任务必须具体</strong>。对比：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我优化一下这段代码</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是一位资深 TypeScript 工程师。</span></span>
<span class="line"><span>请优化下面的工具函数，要求：</span></span>
<span class="line"><span>1. 补全参数和返回值的类型标注，不使用 any；</span></span>
<span class="line"><span>2. 保持函数签名不变；</span></span>
<span class="line"><span>3. 只输出优化后的代码，不需要解释。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>后者的输出质量和可控性明显更好，因为模型不需要猜测「优化」的定义。</p><h2 id="常用技巧" tabindex="-1">常用技巧 <a class="header-anchor" href="#常用技巧" aria-label="Permalink to &quot;常用技巧&quot;">​</a></h2><h3 id="清晰具体的指令" tabindex="-1">清晰具体的指令 <a class="header-anchor" href="#清晰具体的指令" aria-label="Permalink to &quot;清晰具体的指令&quot;">​</a></h3><p>把模糊形容词换成可验证的标准。「写得简洁一点」不如「控制在 200 字以内」；「专业一点」不如「面向有三年经验的前端工程师，使用规范术语」。</p><h3 id="用分隔符隔离上下文" tabindex="-1">用分隔符隔离上下文 <a class="header-anchor" href="#用分隔符隔离上下文" aria-label="Permalink to &quot;用分隔符隔离上下文&quot;">​</a></h3><p>当提示词里包含大段参考材料时，用分隔符明确「指令」和「材料」的边界：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请总结三引号内文章的核心观点，输出为不超过 5 条的中文列表：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;&quot;&quot;</span></span>
<span class="line"><span>（这里粘贴原文）</span></span>
<span class="line"><span>&quot;&quot;&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>常见分隔符有 <code>&quot;&quot;&quot;</code>、XML 标签（<code>&lt;article&gt;&lt;/article&gt;</code>）、<code>---</code> 等，形式不关键，关键是让模型能区分指令与数据。</p><h3 id="少样本示例-few-shot" tabindex="-1">少样本示例（Few-shot） <a class="header-anchor" href="#少样本示例-few-shot" aria-label="Permalink to &quot;少样本示例（Few-shot）&quot;">​</a></h3><p>先给一两个输入输出示例，再让模型按示例处理新输入，适合格式敏感的任务：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>将下面的提交信息改写为规范化格式，参考示例：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输入：修了个登录的bug</span></span>
<span class="line"><span>输出：fix(login): 修复登录状态下 token 过期未刷新的问题</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输入：加了暗黑模式</span></span>
<span class="line"><span>输出：feat(theme): 新增暗黑主题模式与切换入口</span></span>
<span class="line"><span></span></span>
<span class="line"><span>现在处理：</span></span>
<span class="line"><span>输入：更新了依赖</span></span>
<span class="line"><span>输出：</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="思维链-chain-of-thought" tabindex="-1">思维链（Chain of Thought） <a class="header-anchor" href="#思维链-chain-of-thought" aria-label="Permalink to &quot;思维链（Chain of Thought）&quot;">​</a></h3><p>对推理类任务，要求模型先分步分析再给结论，可以减少跳步错误：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请一步步分析这段代码的时间复杂度，说明每一步的推导过程，最后单独给出结论。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="迭代优化" tabindex="-1">迭代优化 <a class="header-anchor" href="#迭代优化" aria-label="Permalink to &quot;迭代优化&quot;">​</a></h3><p>提示词很少一次写好。推荐的迭代流程：</p><ol><li>先用最简单的指令跑一遍，看输出差在哪里；</li><li>针对不满意的地方追加约束（太长就限字数，跑题就补上下文，格式乱就给示例）；</li><li>每次只改一个变量，确认改动是否有效，避免「改了很多但不知道哪条起作用」。</li></ol><h2 id="场景模板" tabindex="-1">场景模板 <a class="header-anchor" href="#场景模板" aria-label="Permalink to &quot;场景模板&quot;">​</a></h2><p>以下模板可直接复制后替换占位内容使用。</p><h3 id="代码生成" tabindex="-1">代码生成 <a class="header-anchor" href="#代码生成" aria-label="Permalink to &quot;代码生成&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是一位资深前端工程师。</span></span>
<span class="line"><span>请用 {技术栈，如 Vue 3 + TypeScript} 实现以下功能：</span></span>
<span class="line"><span>{功能描述}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. {具体要求，如：组件拆分合理、事件命名清晰}；</span></span>
<span class="line"><span>2. 代码中的注释使用中文；</span></span>
<span class="line"><span>3. 先给出文件结构，再给出完整代码。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>当代码生成任务有明确的交付形态和质量标准时，可以把约束写得更完整。下面是一个创意编程（3D 可视化）的进阶范例，输出格式、资源、交互、性能、可维护性全部是可验证的要求：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我做一个单文件的 HTML 网页，用 Three.js 实现一个可以自由浏览的 3D 场景。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>场景是：</span></span>
<span class="line"><span>【你想要的画面，越具体越好。比如：重庆洪崖洞的夜景，层层叠叠的吊脚楼亮着暖黄色的灯，前面是嘉陵江，江上有游船，旁边是千厮门大桥，远处是城市的楼群】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 所有模型和贴图都用代码生成，不要引用任何外部的图片和模型文件；</span></span>
<span class="line"><span>2. 支持鼠标拖动旋转视角、滚轮缩放；</span></span>
<span class="line"><span>3. 画面要有氛围感，重点处理光照、雾气和色调；</span></span>
<span class="line"><span>4. 在普通的笔记本上也要流畅，加载的时候显示进度；</span></span>
<span class="line"><span>5. 主要物体都做成独立的组件，方便我后面单独修改。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>注意【】里的场景描述是变量：约束固定、创意可替换，换一段画面描述就能复用整段模板。</p><h3 id="视觉评审循环" tabindex="-1">视觉评审循环 <a class="header-anchor" href="#视觉评审循环" aria-label="Permalink to &quot;视觉评审循环&quot;">​</a></h3><p>面向视觉类产出（页面、3D 场景、海报等）的自动迭代工作流。它与一次性提示词不同，编排的是「实现 → 截图 → 独立评审 → 修改」的收敛循环，与上面的创意编程模板天然配对：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每改完一版，用浏览器打开它，从几个固定的角度各截一张图。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>再开一个子 Agent，只给它看截图，不给它看代码，</span></span>
<span class="line"><span>让它以一个挑剔的美术指导的角度，按严重程度列出画面问题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你按它的意见改，一直改到它只剩小问题为止。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>这段提示词的四个关键设计：</p><ol><li><strong>只给截图不给代码</strong>：强制评审从最终效果出发，防止被实现细节带偏，是「分隔符隔离上下文」在评审场景的变体；</li><li><strong>评审角色化</strong>：「挑剔的美术指导」用苛刻人设拉高验收标准——角色要素用在评审方而非执行方；</li><li><strong>实现与评审分离</strong>：子 Agent 只负责挑毛病，避免「自己改自己审」的确认偏差，对应开发中的 author / reviewer 分工；</li><li><strong>可验证的终止条件</strong>：「只剩小问题」给循环明确的收敛信号，避免无限迭代。</li></ol><p>「固定的角度」同样重要：每轮评审输入一致，问题才可对比、可验证收敛。</p><h3 id="代码审查" tabindex="-1">代码审查 <a class="header-anchor" href="#代码审查" aria-label="Permalink to &quot;代码审查&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是一位代码审查者。</span></span>
<span class="line"><span>请审查下面的代码，按以下维度逐项给出意见：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 正确性：是否有逻辑错误或边界问题；</span></span>
<span class="line"><span>2. 可读性：命名与结构是否清晰；</span></span>
<span class="line"><span>3. 性能：是否存在明显的性能问题；</span></span>
<span class="line"><span>4. 安全性：是否存在注入、XSS 等风险。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>对每个问题标注严重程度（高 / 中 / 低），并给出修改建议。</span></span>
<span class="line"><span>没有问题的维度直接写「无」。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;&quot;&quot;</span></span>
<span class="line"><span>{粘贴代码}</span></span>
<span class="line"><span>&quot;&quot;&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><h3 id="文档总结" tabindex="-1">文档总结 <a class="header-anchor" href="#文档总结" aria-label="Permalink to &quot;文档总结&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请总结下面的文档，输出结构：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 一句话概括</span></span>
<span class="line"><span>{...}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 核心要点</span></span>
<span class="line"><span>{不超过 5 条}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 值得注意的细节</span></span>
<span class="line"><span>{容易被忽略但重要的信息}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>用简体中文输出，保留关键术语的英文原文。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;&quot;&quot;</span></span>
<span class="line"><span>{粘贴文档}</span></span>
<span class="line"><span>&quot;&quot;&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><h3 id="翻译润色" tabindex="-1">翻译润色 <a class="header-anchor" href="#翻译润色" aria-label="Permalink to &quot;翻译润色&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请将下面的英文技术文章翻译为中文：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 专业术语保留英文（如 hook、tree shaking）；</span></span>
<span class="line"><span>2. 符合中文技术文档的表达习惯，不要逐词直译；</span></span>
<span class="line"><span>3. 译文后单独列出你不确定如何翻译的术语对照表。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;&quot;&quot;</span></span>
<span class="line"><span>{粘贴原文}</span></span>
<span class="line"><span>&quot;&quot;&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="项目审计与治理" tabindex="-1">项目审计与治理 <a class="header-anchor" href="#项目审计与治理" aria-label="Permalink to &quot;项目审计与治理&quot;">​</a></h3><p>面向 AI 编码助手的全仓库治理任务，与针对单段代码的审查不同，要点是<strong>用枚举词定义问题边界，并约定分级行动</strong>：让助手自主处理有把握的部分，不确定的部分只汇报不动手，人工兜底。最简形式只需要两句话：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阅读这整个项目，找出所有损坏的、不一致的、低效的、或者不再需要的内容。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>修复你有把握的部分，把剩下的列出来供我审查。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>需要更可控的输出时，可以扩展为结构化版本：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请审计整个项目，范围包括源码、配置和文档。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>问题定义（按以下四类查找）：</span></span>
<span class="line"><span>1. 损坏的：无法运行、引用不存在的文件或路由；</span></span>
<span class="line"><span>2. 不一致的：同类内容写法或风格互相矛盾；</span></span>
<span class="line"><span>3. 低效的：明显可简化或存在重复的部分；</span></span>
<span class="line"><span>4. 不再需要的：失效链接、过时内容、无引用的孤立文件。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>处理规则：</span></span>
<span class="line"><span>1. 有把握的问题直接修复，并逐条说明改了什么、为什么；</span></span>
<span class="line"><span>2. 没把握的部分不要改动，列成清单附上理由，供我审查后决定。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">适用性说明</p><p>仓库级审计的范围越大，越要注意让助手「小步提交、逐项汇报」，一次性放开全仓库自动修改容易误伤无关内容。</p></div>`,51)])])}const h=n(l,[["render",i]]);export{o as __pageData,h as default};
